1.4 控制语句相关关键字
1、 if 语句
形式：

if(条件表达式)

{ &#x2F;&#x2F;复合语句，若干条语句的集合
语句 1;
语句 2；
}
如果条件成立执行大括号里的所有语句，不成立的话大括号里的语句不执行
#include &lt;stdio.h&gt;int main()&#123;	int a=10;	if(a&gt;5)	&#123;		printf(&quot;a&gt;5\n&quot;);	&#125;	return 0;&#125;


if(条件表达式)

{
语句块 1
}
else
{
语句块 2
}
if else 语句的作用是，如果 if 的条件成立，执行 if 后面{}内的语句，否则执行 else 后的语句
#include &lt;stdio.h&gt;int main()&#123;	int a=10;	if(a&gt;5)	&#123;		printf(&quot;a&gt;5\n&quot;);	&#125;	else	&#123;		printf(&quot;a&lt;=5\n&quot;);	&#125;	return 0;	&#125;


if(条件表达式)

{
}
else if(条件表达式)
{
}
else if(条件表达式)
{
}
else
{
}
在判断的时候，从上往下判断，一旦有成立的表达式，执行对应的复合语句， 下边的就不再判断了，各个条件判断是互斥的
#include &lt;stdio.h&gt;int main(void)&#123;	char ch;	float score = 0;	printf(&quot;请输入学生分数:\n&quot;);	scanf(&quot;%f&quot;,&amp;score);	if(score&lt;0 || score &gt;100)	&#123;		printf(&quot;你所输入的信息有错\n&quot;);		return 0;	&#125;	else if( score&lt;60)	&#123;		ch = &#x27;E&#x27;;	&#125;	else if ( score &lt; 70 )	&#123;		ch = &#x27;D&#x27;;	&#125;	else if ( score &lt; 80 )	&#123;		ch = &#x27;C&#x27;;	&#125;	else if ( score &lt; 90 )	&#123;		ch = &#x27;B&#x27;;	&#125;	else	&#123;		ch = &#x27;A&#x27;;	&#125;	printf(&quot;成绩评定为：%c\n&quot;,ch);	return 0;	&#125;

2、 switch 语句
switch（表达式）&#x2F;&#x2F;表达式只能是字符型或整型的(short int int long int)
{
case 常量表达式 1：
语句 1；
break；
case 常量表达式 2：
语句 2;
break；
default：
语句 3；
break;
}
#include &lt;stdio.h&gt;int main(int argc, char *argv[])&#123;	int n;	printf(&quot;请输入一个 1~7 的数\n&quot;);	scanf(&quot;%d&quot;,&amp;n);	switch(n)	&#123;		case 1:			printf(&quot;星期一\n&quot;);			break;		case 2:			printf(&quot;星期二\n&quot;);			break;		case 3:			printf(&quot;星期三\n&quot;);			break;		case 4:			printf(&quot;星期四\n&quot;);			break;		case 5:			printf(&quot;星期五\n&quot;);			break;		case 6:			printf(&quot;星期六\n&quot;);			break;		case 7:			printf(&quot;星期天\n&quot;);			break;		default:			printf(&quot;您的输入有误，请输入 1~7 的数\n&quot;);			break;	&#125;		return 0

1.4.2 循环控制语句相关的关键字
1、 for 循环
for(表达式 1;表达式 2;表达式 3)
{&#x2F;&#x2F;复合语句，循环体
}
第一次进入循环的时候执行表达式 1，表达式 1 只干一次，
表达式 2，是循环的条件，只有表达式 2 为真了，才执行循环体，也就是说
每次进入循环体之前要判断表达式 2 是否为真。
每次执行完循环体后，首先执行表达式 3
#include &lt;stdio.h&gt;int main(void)&#123;	int i;	int sum=0;	for(i=1;i&lt;=100;i++)	&#123;		sum = sum+i;	&#125;		printf(&quot;sum=%d\n&quot;,sum);		return 0;	&#125;//例 26：#include &lt;stdio.h&gt;int main(int argc, char *argv[])&#123;	int i,j;	for(i=1;i&lt;=9;i++)	&#123;	for(j=1;j&lt;=i;j++)	&#123;		printf(&quot;%d*%d=%d &quot;,i,j,i*j);	&#125;		printf(&quot;\n&quot;);	&#125;		return 0;	&#125;

2、 while 循环

形式 1：

while(条件表达式)
{&#x2F;&#x2F;循环体，复合语句
}
进入 while 循环的时候，首先会判断条件表达式是否为真，为真进入循环体，否则退出循环
#include &lt;stdio.h&gt;int main(void)&#123;/* 2) 形式 1：while(条件表达式)&#123;//循环体，复合语句&#125;*/	int i=1;	int sum=0;	while(i&lt;=100)	&#123;		sum = sum+i;		i++;	&#125;		printf(&quot;sum=%d\n&quot;,sum);	return 0;&#125;


形式 2 ： do

do{&#x2F;&#x2F;循环体
}while(条件表达式);
先执行循环体里的代码，然后去判断条件表达式是否为真，为真再次执行循环体，否则退出循环
#include &lt;stdio.h&gt;int main(void)&#123;	int i=1;	int sum=0;	do	&#123;		sum = sum+i;		i++;	&#125;while(i&lt;=100);		printf(&quot;sum=%d\n&quot;,sum);	return 0;&#125;

形式 1 和形式 2 的区别是，形式 1 先判断在执行循环体，形式 2 先执行循环体，再判断
break 跳出循环
continue 结束本次循环，进入下一次循环
#include &lt;stdio.h&gt;int main(void)	&#123;		int i;		int sum=0;	for(i=1;i&lt;=100;i++)	&#123;		if(i==10)		break;//将 break 修改成 continue 看效果		sum = sum+i;	&#125;		printf(&quot;sum=%d\n&quot;,sum);		return 0;	&#125;	return 0;//返回函数的意思。结束 return 所在的函数，//在普通函数中，返回到被调用处，在 main 函数中的话，结束程序

3、 goto
#include &lt;stdio.h&gt;int main(int argc, char *argv[])&#123;	printf(&quot;test000000000000000000\n&quot;);	printf(&quot;test1111111111111111\n&quot;);	goto xiutao;	printf(&quot;test222222222222222222\n&quot;);	printf(&quot;test3333333333333333\n&quot;);	printf(&quot;test444444444444444444444\n&quot;);	printf(&quot;test55555555555555555555\n&quot;);	xiutao:	printf(&quot;test66666666666666666\n&quot;);	return 0;&#125;

1.线性表的定义线性表：零个或多个数据元素的有限序列。 它是一个序列。如果有多个元素，则第一个元素无前驱，最后一个元素无后继，其他的每一个元素只有一个前驱和后继。 将线性表记为 a1，a2，a3，则a1是a2的直接前驱元素，a3是a2的直接后继元素。有且仅仅只有一个直接前驱和一个直接后继。 所以线性表元素的个数n(n≥0)定义为线性表的长度，当n＝0，为空表。 在非空表中的每个元素都有一个确定的位置，比如a1是第一个，a3是最后一个。a2是第二个，称2为数据元素a2在线性表中的位序。 2.线性表的抽象数据类型当传递一个参数给函数的时候，这个参数会不会在函数内被改动决定了使用什么参数形式。 如果需要被改动，则需要传递指向这个参数的指针。 如果不用被改动可以直接传递这个参数。 总结：需要改动则传递参数的指针，不需要则传递这个参数。 3.线性表的顺序存储结构顺序存储结构线性表的顺序存储结构，指的是用一段地址连续的存储单元依次存储线性表的数据元素。 说白了就是：在内存中，占个地方，通过占位的形式，将一定的内存空间给占，然后把相同数据类型的数据元素一次存放在这里。 使用一维数组来实现顺序存储结构
数据长度与线性表长度的区别数组的长度是存放线性表的存储空间长度。 线性表的长度是线性表中数据元素的个数，会变化。 地址计算方法C语言中的数组是从0开始为第一个下标。所以线性表的第i个元素是要存储在数组下标为i-1的位置。 存储器中的每个存储单元都有自己的编号，这个编号为地址。 假设占用的是c个存储单元，那么线性表中第i+1个数据元素的存储位置和第i个数据元素的存储位置满足以下关系（LOC表示获得存储位置的函数）
例如：如果LOC(1)为第一个元素的地址，每个元素占用4个存储单元，即C&#x3D;4，那么第二个元素LOC(2)，就是LOC(1)+4 所以对于第i个数据元素ai的存储位置可以得出ai：
4.顺序存储结构的插入与删除获得元素操作// 定义两个宏，分别表示函数执行成功和失败的状态#define OK 1#define ERROR 0// 定义一个新的类型名Status，它实际上就是int类型typedef int Status;// 函数声明：从顺序表L中获取第i个位置的元素，并将其赋值给变量e// SqList L:顺序表结构体// int i:表示获取元素的位置，也就是索引// ElemType *e:这是一个指针，用于存放获取到的元素。Status GetElem(SqList L, int i, ElemType *e) &#123; // 检查i是否在合法范围内，即i大于0且小于等于顺序表的长度 if (i &lt; 1 || i &gt; L.length) &#123; // 如果i不合法，返回错误状态ERROR return ERROR; &#125; // 如果i合法，将第i个位置的元素赋值给e指向的变量 // 注意：由于数组索引是从0开始的，所以第i个元素实际上是L.data[i-1] *e = L.data[i - 1]; // 返回成功状态OK return OK;&#125;
插入操作// 函数声明，用于在顺序表L中第i个位置插入元素e，并返回操作状态Status ListInsert(SqList *L, int i, ElemType e) &#123; int k; // 检查顺序表是否已满，如果已满，返回错误状态 if (L-&gt;length == MAXSIZE) return ERROR; // 检查插入位置i是否合法，如果不合法（小于1或大于顺序表长度+1），返回错误状态 if (i &lt; 1 || i &gt; L-&gt;length + 1) return ERROR; // 如果插入位置不在表尾 if (i &lt;= L-&gt;length) &#123; // 从最后一个元素开始，直到要插入的位置，将每个元素向后移动一位 for (k = L-&gt;length - 1; k &gt;= i - 1; k--) &#123; // 将元素向后移动 L-&gt;data[k + 1] = L-&gt;data[k]; &#125; &#125; // 将新元素e插入到位置i-1（因为数组索引从0开始） L-&gt;data[i - 1] = e; // 顺序表长度增加1 L-&gt;length++; // 插入成功，返回成功状态 return OK;&#125;
删除操作// 函数声明，从顺序表L中删除第i个位置的元素，并通过e返回该元素的值，函数返回操作状态Status ListDelete(SqList *L, int i, ElemType *e)&#123; int k; // 检查顺序表是否为空，如果为空，返回错误状态 if(L-&gt;length == 0) return ERROR; // 检查删除位置i是否正确，即i是否在1到L-&gt;length的范围内，如果不正确，返回错误状态 if(i &lt; 1 || i &gt; L-&gt;length) return ERROR; // 将要删除的元素赋值给*e，即通过指针e返回被删除元素的值 *e = L-&gt;data[i-1]; // 如果删除的位置不是最后一个元素，则需要将后续元素前移 if(i &lt; L-&gt;length)&#123; for(k = i; k &lt; L-&gt;length; k++)&#123; // 将位置k的元素前移到位置k-1 L-&gt;data[k-1] = L-&gt;data[k]; &#125; &#125; // 顺序表的长度减1，因为已经删除了一个元素 L-&gt;length--; // 如果删除操作成功，返回OK return OK;&#125;
线性表顺序存储结构的优缺点 5.线性表的链式存储结构顺序存储结构不足的解决办法缺点：插入和删除需要移动大量元素 线性表链式存储结构定义特点：用一组任意的存储单元存储线性表的数据元素，这组存储单元可以是连续，也可以不是连续。 存储数据元素信息的域称为数据域，存储直接后继位置的域称为指针域。 指针域存储的信息称为指针或链。这两部分信息组成数据元素ai的存储映像，为结点。 n个结点（ai的存储映像）链结成一个链表，即为线性表的链式存储结构，因此链表的每个节点只包含每个指针域，称为单链表。 单链表：通过每个节点的指针将线性表的数据元素按照逻辑次序链接在一起。
链表中第一个节点的存储位置叫做头指针，所以整个链表的存储从头指针开始。之后的每一个节点，就是上一个后继指针指向的位置。最后一个，直接后继不存储，所以线性链表的最后一个节点指针为“NULL”。
为了方便会在单链表的第一个节点前设一个头节点。
头指针与头节点的区别 线性表链式存储结构代码描述若线性表为空，则头节点的指针域为空
带有头节点的单链表，如下
空链表如下
// 定义链表节点结构体typedef struct None &#123; int data; // 数据域 struct None *next; // 指向下一个节点的指针&#125; Node; // 使用 Node 作为别名typedef struct None *Link; // 定义指向 Node 的指针类型 Link
从代码中来看： 结点由存放数据元素的数据域，存放后继节点地址的指针域组成。
单链表的读取算法思路： （1）声明一个指针p指向链表的第一个结点，初始化j从1开始。 （2）当j&lt;i时，遍历链表，让p的指针向后移动，不断指向下一结点，j累加i。 （3）若到链表末尾p为空，则说明第i个结点不存。 （4）否则查找成功，返回结点p的数据。 static GetElem(LinkList L, int i, ElemType *e)&#123; int j; //声明结点p p = L-&gt;next; //让p指向链表L的第一个结点 j = 1; //j为计数器 while (p &amp;&amp; j &lt; i) //p不为空或计算器j还没有等于i时，循环继续 &#123; p = p-&gt;next; //让p指向下一个结点 j++; &#125; if (!p || j &gt; i) &#123; return ERROR; //第i个不存在 &#125; *e = p-&gt;data; //读取第i个元素的数据 return OK;&#125;// ||：一个为真，则都为真 &amp;&amp;：要两个都为真
单链表的插入与删除插入算法思路（1）声明一个指针p指向链表头结点，初始化j从1开始。 （2）当j&lt;i时，就遍历链表，让p的指针向后移动，不断指向下一个结点，j累加1； （3）若到链表末尾p为空，则说明第i个结点不存在。 （4）否则查找成功，在系统中生成一个空结点s。 （5）将数据元素e赋值给s-&gt;data。 （6）单链表的插入标准语句s-&gt;next &#x3D; p-&gt;next; p-&gt;next &#x3D; s; （7）返回成功。 static GetElem(LinkList L, int i, ElemType *e)&#123; int j; LinkList p = L-&gt;next; // 假设 L 是头结点，p 指向第一个数据结点 j = 1; // 初始化计数器，从第 1 个结点开始 while (p &amp;&amp; j &lt; i) // 遍历链表，直到找到第 i 个结点 &#123; p = p-&gt;next; j++; &#125; if (!p || j &gt; i) // 如果链表为空或者 j 超过了 i，返回错误 &#123; return ERROR; &#125; // 插入新结点 LinkList s = (LinkList)malloc(sizeof(Node)); // 为新结点分配内存 s-&gt;data = e; s-&gt;next = p-&gt;next; // 将p的后继结点赋值给s的后继 p-&gt;next = s; // 将s赋值给p的后继 return OK;&#125;
删除算法思路（1）声明一个指针p指向链表头结点，初始化j从1开始。 （2）当j&lt;i时，就遍历链表，让p的指针向后移动，不断指向下一个结点，j累加1； （3）若到链表末尾p为空，则说明第i个结点不存在。 （4）否则查找成功，将要删除的结点p-&gt;next赋值给q。 （5）单链表的删除标准语句p-&gt;next &#x3D; q-&gt;next。 （6）将q结点中的数据赋值给e，作为返回 （7）释放q结点。 （8）返回成功。 static GetElem(LinkList L, int i, ElemType *e)&#123; int j; p = L-&gt;next; // 初始化 p 指针，指向链表的第一个节点 j = 1; // 从第 1 个节点开始计数 while (p &amp;&amp; j &lt; i) // 遍历链表，找到第 i 个节点的前一个节点 &#123; p = p-&gt;next; j++; &#125; if (!p || j &gt; i) // 如果链表长度不足 i，或者 j 超过 i，返回错误 &#123; return ERROR; &#125; q = p-&gt;next; // 找到要删除的节点 q（即第 i 个节点） p-&gt;next = q-&gt;next; // 让 p 的后继指针跳过 q，指向 q 的后继节点 *e = q-&gt;data; // 将要删除的节点 q 的数据保存到 e 中 free(q); // 释放被删除节点 q 所占的内存 return OK; // 返回成功&#125;
单链表的整表创建（1）声明一个指针p和计算器变量i。 （2）初始化一空链表L。 （3）让L的头结点的指针指向NULL，建立一个带头结点的单链表。 （4）循环。 1、生成一个新节点赋值给p。 2、随机生成一个数字赋值给p的数据域p-&gt;data。 3、将p插入到头结点与前一新结点之间。 static GetElem(LinkList L, int i, ElemType *e)&#123; LinkList p; // 定义一个指针 p 用于遍历链表 int i; // 定义计数器 i（注意：与外部函数参数 i 冲突） srand(time(0)); // 初始化随机数种子，确保每次运行时生成不同的随机数 *L = (LinkList)malloc(sizeof(LNode)); // 为头节点分配内存 (*L)-&gt;next = NULL; // 将头节点的后继指针设为 NULL，表示链表初始化为空 for (i = 0; i &lt; n; i++) // 循环生成 n 个节点 &#123; p = (LinkList)malloc(sizeof(LNode)); // 为新节点 p 分配内存 p-&gt;data = rand() % 100 + 1; // 生成 1 到 100 之间的随机数，并赋给 p-&gt;data p-&gt;next = (*L)-&gt;next; // 将当前链表的第一个节点赋值为 p 的后继 (*L)-&gt;next = p; // 将 p 插入到头节点之后 &#125;&#125;
循环链表循环链表和单链表的差异是p-&gt;netx是判断是否为空，循环链表的判断是p-&gt;next不等于头结点。
P = rearA -&gt; next; //保存A表的头结点，1点rearA -&gt; next = rearB -&gt; next -&gt; next; //将本是指向B表的第一个结点（不是头结点）q = rearB -&gt; next; rearB -&gt; next = p; //赋值给rearA-&gt;next,2点free(q); //释放q
双向链表双向链表：是在单链表的每个节点中，在设置一个指向前驱结点的指针域。 typedef struct DulNode&#123; ElemType data; struct DuLNode *prior; //直接前驱指针 struct DuLNone *next; //直接后继指针&#125;DulNode,*DuLinkList;
总结

一、函数的概念函数是 c 语言的功能单位，实现一个功能可以封装一个函数来实现。 定义函数的时候一切以功能为目的，根据功能去定函数的参数和返回值。 二、函数的分类1、定义角度分类1、库函数 2、自定义函数 3、系统调用 2、参数角度分类1、有参函数 ​ 函数有形参，可以是一个，也可以是多个，类型随便 例如： int fun(int a.float b.double c)&#123;&#125;int max(int x,int y)&#123;&#125;
2、无参函数 函数没有参数，在形参列表的位置写 void 或者不写 int fun(void)&#123;&#125;int fun()&#123;&#125;
3、返回值角度分类 （1）带返回值的函数 在定义函数的时候，必须带有返回值类型，在函数题，必须有 return，没有返回值类型，默认返回值整形 例如： char fun() //定义一个返回字符数据的函数&#123; char b = &#x27;a&#x27;; return b;&#125;
fun()&#123; return 1;&#125;
（2）没有返回值的函数 在定义函数的时候，函数名字前面加个 void void fun(形参表)&#123; ; ; return ; ;&#125;
在函数中不需要 return，如果想结束函数，返回到被调用的地方，return ;什么都不返回 #include &lt;stido.h&gt;int main(int x,int y)&#123; int z; if(x&gt;y) z=x; else z=y; return z;&#125;void help(void)&#123; printf(&quot;*********************
&quot;); printf(&quot;********帮助信息*****
&quot;); printf(&quot;*********************
&quot;);&#125;int main()&#123; int num; help(); num = max(10,10+5); printf(&quot;num=%d
&quot;,num); return 0;&#125;
三、函数的定义1、定义方法 返回值类型 函数名字（形参列表）{ ​ &#x2F;&#x2F;函数体，函数的功能写在函数体实现 } //定义一个没有参数也没有返回值的函数void myfun1()&#123; printf(&quot;hello world
&quot;);&#125;return ;//定义一个有参数的函数void myfun2()&#123; int sum; sum = a + b; printf(&quot;%d + %d = %d
&quot;, a , b , sum);&#125;//定义一个有返回值的函数int myfun3(int a,int b)&#123; int sum; sum = a + b; return sum;&#125;
四、函数的声明1、概念 对已经定义的函数，进行声明，可以多次 2、为什么声明 编译器在编译 c 时，上到下编译 3、声明方法 （1）主调函数和被调函数在同一个.c 中 void fun(void)&#123; printf(&quot;hello world
&quot;);&#125;int main()&#123; fun();&#125;//不需要声明
（2）被调函数在下，主函数在上 int main()&#123; fun();&#125;void fun(void)&#123; printf(&quot;hello world
&quot;);&#125;//需要声明//1.直接声明#include &lt;stdio.h&gt;void myfun1();void myfun2(int a,int b);int myfun3(int a,int b);int main()&#123; myfun1(); return 0;&#125;void myfun1()&#123; printf(&quot;hello world
&quot;); return ;&#125;void myfun2(int a,int b)&#123; int sum; sum = a + b; printf(&quot;%d + %d = %d
&quot;,a,b,sum);&#125;int myfun3(int a,int b)&#123; int sum; sum = a + b; return sum;&#125;//2.间接声明//a.c文件#include &quot;a.h&quot;int main()&#123; fun();&#125;void fun(void)&#123; printf(&quot;hellow world&quot;);&#125;//a.h文件extern void fun(void);
（2）主调函数和被调函数不在同一个.c 文件 1.直接声明 2.间接声明 //myfun.c#include &quot;myfun.h&quot;void myfun1()&#123; printf(&quot;hellow world
&quot;); return;&#125;//myfun.h#ifndef MYFUN_H#define MYFUN_Hvoid myfun1();#endif//main.c#include &lt;stdio.h&gt;#include &quot;myfun.h&quot;int main()&#123; muyfun1(); return 0;&#125;
五、函数调用变量 &#x3D; 函数名（实参列表）；带返回值 函数名（实参列表）；不带返回值 #include &lt;stdio.h&gt;void myfun1();void myfun2(int a,int b);int myfun(int a,int b);int main()&#123; //没有参数也没有返回值 myfun1(); printf(&quot;*******************
