#include &lt;stdio.h&gt;int main()&#123;    int a = 100;    int * p;//指针变量    p = &amp;a;//a的地址保存在p中    printf(&quot;a = %d %d\n&quot;,a,*p);    ptintf(&quot;&amp;a = %p %p\n&quot;,&amp;a,p);&#125;


