如果想让不同类型的指针互相赋值，需要强制类型转换
#include &lt;stdio.h&gt;int main()&#123;    int a=0x1234,b=5678;    char *p1,*p2;    printf(&quot;%#x %#x\n&quot;,a,b);    p1=(char *)&amp;a;    p2=(char *)&amp;b;    printf(&quot;%#x %#x\n&quot;,*p1,*p2);    p1++;    p2++;    printf(&quot;%#x %#x\n&quot;,*p1,*p2);&#125;



五、指针和数组元素之间的关系1、数组元素和指针的基本关系
变量存放在内存中，有地址编号，定义的数组，是的哟个相同类型的变量的集合。每个变量都占内存空间，都有地址编号。指针变量可以存放数组元素的地址（数组首元素）
int a[10];//int *p =&amp;a[0];int *p;p=&amp;a[0]; //指针变量p保存了数组a中第0个元素的地址，即a[0]的地址

2、数组元素的引用方式
（1）数组名[下标]
int a[10];a[2]=100;

（2）指针名加下标
int a[10];int *p;p=a;p[2]=100;

（3）指针运算加取值
int a[10];int *p;p = a;*(p+2)=100;//a[2]=100

#include &lt;stdio.h&gt;int main()&#123;    int a[5]=&#123;0,1,2,3,4&#125;;    int *p;    p=a;    printf(&quot;a[2]=%d\n&quot;,a[2]);//2    printf(&quot;p[2]=%d\n&quot;,p[2]);//2    printf(&quot;*(p+2) = %d\n&quot;,*(p+2));//2 	printf(&quot;*(a+2) = %d\n&quot;,*(a+2));//2 	printf(&quot;p=%p\n&quot;,p); 	printf(&quot;p+2=%p\n&quot;,p+2); 	printf(&quot;&amp;a[0] = %p\n&quot;, &amp;a[0]); 	printf(&quot;&amp;a[2] = %p\n&quot;, &amp;a[2]);&#125;

栈的定义栈（stack）是限定仅在表尾进行插入和删除操作的线性表。（指的是栈顶）栈顶：插入和删除的一端栈底：另外一段空栈：不含任何数据元素的栈栈又称：后进先出的线性表，简称LIFO结构 注意：栈元素具有线性表关系，即前驱后继关系。特殊之处就是这个线性表的插入和删除位置，只能在栈顶进行。栈底是固定的，最先进栈的只能在栈底。 栈的插入操作叫做进栈，也叫压栈、入栈。 栈的删除操作，叫做出栈，也叫弹栈。
栈的抽象数据类型push：插入（进栈） pop：删除（出栈） ADT 栈（stack）Data 同线性表。元素具有相同的类型，相邻元素具有前驱和后继关系。operation InitStack(*S):初始化操作，建立一个空栈s。 DestroyStack(*S):若栈存在，则销毁它。 CleanrStack(*S):将栈清空。 StackEmpyt(S):若栈为空，返回true，否则返回false。 GetTop(S,*e):若栈存在且非空，用e返回s的栈元素 Push(*S,e):若栈s存在，插入新元素e到栈s中并称为栈顶元素。 StatckLengtg(S):返回栈s的元素个数。endADT
栈的顺序存储结构及实现栈的顺序存储结构栈的顺序结构其实就是线性表顺序存储的简化，称为顺序栈。 typedef int SElemType; //SElemType类型根据实际情况typedef struct&#123; SElemType data[MAXSIZE]; int top; //栈顶指针&#125;SqStack;
栈的顺序存储结构-进栈//插入元素e为新的栈顶元素Status Push(SqStack *S,SElemType)&#123; if(S-&gt;top == MAXSIZE -1)&#123; //如果栈满 return ERROR; &#125; S-&gt;top++; //栈顶指针加1 S-&gt;data[S-&gt;top]=e; //将新插入元素赋值给栈顶空间 return OK;&#125;
栈的顺序存储结构–出栈操作//若栈不为空，则删除S的栈顶元素怒，用e返回其值，并返回OK，否则ERRORStatus Pop(SqStack *S,SElemType *e)&#123; if(S-&gt;top==-1)&#123; return ERROR; &#125; *e=S-&gt;data[S-&gt;top]; //将要删除栈顶元素赋值给e S-&gt;top--;//栈顶指针减一 return OK;&#125;
两站共享空间typedef struct&#123; SElemType data[MAXSIZE]; int top1; //栈1栈顶指针 int top2; //栈2栈顶指针&#125;SqDoubleSatck;
两站共享空间的push方法 Status Push(SqDoubleStack *S,SElemType e,int stackNumber)&#123; if(S-&gt;top1+1=S-&gt;top2) //栈满了 return ERROR; if(statckNumber==1) //栈1有元素进栈 S-&gt;data[++S-&gt;top1]=e //如果是栈1则线top1+1后 给数组元素赋值 else if(statckNumber==2) //栈2有元素进栈 S-data[--S-&gt;top2]=e //如果是栈2，则线top2-1后 给数组元素赋值 return OK;&#125;
两站共享空间的pop方法，判断只是栈1栈2的参数stackNumberStatus Pop(SqDoubleStack *S,SElemType *e,int stackNumber)&#123; if(statckNumber == 1) &#123; if(S-&gt;top = -1) return ERROR; *e = S-&gt;data[S-&gt;top1--1]; //将栈1的栈顶元素出栈 &#125; else if(stackNumber == 2)&#123; if(S-&gt;top2==MAXSIZE) return ERROR; *e = S-&gt;data[S-&gt;top2++]; //栈2的栈顶元素出栈 &#125; return OK;&#125;
栈的链式存储结构以及实现栈的链式存储结构栈的链式存储结构，简称为链栈。 链栈代码定义： typedef struct StackNode&#123; SElemType data; struct StatckNode *next;&#125;typedef struct&#123; LinkStackPrt top; int count;&#125;LinkStack;
栈的链式存储结构–进栈操作 Status Push(LinkStack *S,SElemType e)&#123; LinkStackPtr s=(LinkStackPrt)malloc(sizeof(StackNode)); s-&gt;data=e; s-&gt;next=S-&gt;top; //把当前栈顶元素赋值给新节点的直接后继。见图1 S-&gt;top=s; //把新的结点s赋值给栈顶指针，见图2 S-&gt;count++; return OK;&#125;
栈的链式存储结构–出栈操作 Status Pop(LinkStack *S,SElemType *e)&#123; LinkStackPrt p; if(StackEmpty(*S)) return ERROR; *e=S-&gt;top-&gt;data; p=S-&gt;top; //将栈顶结点赋值给p，见图3 S-&gt;top=S-&gt;top-&gt;next; //使得栈顶指针下移一位，指向后一个结点，见图4 free(p); //释放结点p S-&gt;count--; return OK;&#125;
使用建议： 如果栈的使用过程中元素变化不可预料，有时候小，有时候大，使用链栈。 如果变化在可控范围内，使用顺序栈。 栈的作用栈的引用同简化了程序设计的问题，划分了不同关注层次，使得思考范围缩小，更加聚焦我们要解决的问题核心。 栈的应用–递归递归：把一个直接调用自己或通过一系列的调用语句间接的调用自己的函数，称为递归函数。 例如： int Fbi(int i)&#123; if(i&lt;2)&#123; return i == 0 ? 0 : 1; &#125; return Fbi(i-1)+Fbi(i-2);&#125;int main()&#123; int i; printf(&quot;递归显示斐波那契数列：\n&quot;); for(i = 0;i&lt;40;i++) printf(&quot;%d&quot;,Fbi(i)); return 0;&#125;
注意的是：每个递归定义必须至少有一个条件，满足递归不再进行，即不再引用自身而是返回值退出。 栈的应用–四则运算表达式求值后缀（逆波兰）表示法的定义一种不需要括号的后缀表达法，称为逆波兰 正常数学表达式：9+（3-1）x3+10÷2 后缀表达式：9 3 1-3 * + 10 2 &#x2F; + 后缀原因在于所有的符号都是在要运算数字的后面。 后缀表达式的计算结果后缀表达式：9 3 1-3 * + 10 2 &#x2F; + 规则：从左到右遍历表达式的每个数字和符号，遇到数字就进栈，遇到符号就将处于栈顶的两个数字出栈，进行运算，运算结果在进栈。 中缀表达式转后缀表达式正常数学表达式：9+（3-1）x3+10÷2也就是中缀表达式。 转换规则：从左到右遍历中缀表达式的每个数字和符号，若是数字就输出，即后缀表达式的一部分。若是符号，判断其与栈顶符号的优先级，是右括号或优先级不高于栈顶符号（乘除优先加减）则栈顶元素一次出栈并输出，将当前符号进栈，一直到输出后缀表达式为止。 队列的定义队列（queue）是只允许在一端进行插入操作，而在另一端进行删除操作的线性表。 队列是一种先进先出的线性表，简称FIFO。允许插入的一段称为队尾，允许删除的一端称为队头。 例如：q&#x3D;(a1,a2,…,an)，那么a1就是队头元素，an就是队尾。
队列的抽象数据类型ADT 队列(Queue)Data 同线性表。元素具有相同的类型，相邻元素具有前驱和后继关系。Operation InitQueue(*Q):初始化操作，建立一个空队列Q DestroyQueue(*Q):若队列Q存在，则销毁 ClearQueue(*Q):将队列Q清空 QueueEmpty(Q):若队列Q为空，返回ture，否则false GetHead(Q,*Q):若队列Q存在且非空，用e返回队头元素 EnQueue(*Q,e):队列Q存在，插入新元素e到队列Q称为队尾元素 DeQueue(*Q,e):删除队列Q中队头元素，并用e返回其值 QueueLength(Q):返回队列Q的元素个数endADT
循环队列队列顺序存储的不足容易出现假溢出 循环队列的定义解决假溢出的办法就是后面满了，再从头开始，头尾相接的循环。这种队列头尾相接的顺序存储结构称为循环队列。 办法1：设置一个标志了flag，当front&#x3D;rear，且flag&#x3D;0时为队列空，当front&#x3D;rear，且flag&#x3D;1时为队列满。 办法2：当队列空时，条件时front&#x3D;rear。当队列满时，修改其条件，保留一个元素空间。也就是数，队列满时，数组还有一个空闲单元。
在第二种方法中，由于rear可能比front大，也可以比front小，若队列的最大尺寸为QueueSize，那么队列满的条件时(rear+1)%QueueSize&#x3D;&#x3D;front（取模的目的时为了整合rear与front大小为一个问题）。比如当QueueSize&#x3D;5，左边的图front&#x3D;0,而rear4，（4+1）%5&#x3D;0，所以此时队列满，再比如右图，front&#x3D;2而rear&#x3D;1，所以（1+1）%5&#x3D;2，所以队列也是满的，对于下图，ftont&#x3D;2,而rear&#x3D;0，(0+1)%5&#x3D;1，1≠2，所以此时队列没有满。
当rear&gt;front，即图1和图2，此时队列的长度为rear-front，但当rear&lt;front，如上图和下图3，队列长度分为两段，一段QueueSize-front，另一段时0+rear，加在一起的长度为rear-front+QueueSzie。
所以通用计算队列长度公式为 (rear - front + QueueSize)%QueueSize 循序队列的顺序存储结构代码如下：typedef int QElemType;typedef struct&#123; QElemType data[MAXSIZE]; int front; //头指针 int rear; //尾指针，队列不为空，指向队列尾元素的下一个位置&#125;SqQueue;
循环队列的初始化代码Status InitQueue(SqQueue *Q)&#123; Q-&gt;front=0; Q-&gt;rear=0; return OK;&#125;
循环队列求队列长度的代码//返回Q的元素个数，也就是队列的当前长度int QueueLength(SqQueue Q)&#123; return (Q.rear - Q.front+MAXSIZE)%MAXSIZE;&#125;
循环队列的入列操作：Status EnQueue(SqQueue *Q,QElemType e)&#123; if((Q-&gt;rear+1)%MAXSIZE==Q-&gt;front)&#123; //队列满判断 return ERROR; &#125; Q-&gt;data[Q-rear]=e; //将元素e赋值给队尾 Q-&gt;rear=(Q-&gt;rear+1)%MAXSIZE; //rear指针向后移动一位，若为最后则转到数组头部 return OK;&#125;
循环队列如队列操作代码：Status EnQueue(SqQueue *Q,QElemType e)&#123; if((Q-&gt;rear+1)%MAXSIZE==Q-&gt;front)//队列满的判断 return ERROR; Q-&gt;data[Q-&gt;rear]=e; //将元素e赋值给队尾 Q-&gt;rear=(Q-&gt;rear+1)%MAXSIZE; //rear指针向后移一位，若到最后则转到数组头部 return OK;&#125;
循环队列的出队列操作代码：Status DeQueue(SqQueue *Q,QElemType *e)&#123; if(Q-&gt;front == Q-&gt;rear) return ERROR; *e=Q-&gt;data[Q-&gt;front]; Q-&gt;front=(Q-&gt;front+1)%MAXSIZE;&#125;
队列的链式存储结构及实现队列的链式存储结构，其实就是线性表的单链表，只不过它只能尾进头出，我们把它简称链队列。
将队头指针指向链队列的头结点，而队尾指针指向终端节点。空队列时，front和rear都指向头结点。 链队列的结构为：typedef int QElemType;typedef struct QNone //结点结构&#123; QElemType data; struct QNone *next;&#125;QNone,*QueuePtr;typedef struct&#123; QueuePtr front,rear;//队头、队尾指针&#125;
队列链式存储结构–入队操作入队操作，其实就是链表尾部插入结点 Status EnQueue(LinkQueue *Q,QElemType e)&#123; QueuePtr s=(QueuePtr)malloc(sizeof(QNone)); if(!s) //存储分配失败 exit(OVERFLOW); s-&gt;data=e; s-&gt;next=NULL; Q-&gt;rear-&gt;next=s; //把拥有元素e的新节点s赋值给原队尾结点的后继 Q-&gt;rear=s; ///把当前的s设置为队尾结点，rear指向s return OK;&#125;
队列的链式存储结构–出队操作出队操作，就是头结点的后继节点出队，将头结点的后继改为它后面的结点，若链表除头结点外只剩下一个元素，则需要将rear指向头结点。
Status DeQueue(LinkQueue *Q,QElemType *e)&#123; QueuePtr p; if(Q-&gt;front==Q-&gt;rear) return ERROR; p=Q-&gt;front-&gt;next;//将要删除的队头结点暂存到p *e=p-&gt;data; //将要删除的队头几点赋值给e Q-&gt;front-&gt;next=p-next; //将队头结点的后继p-&gt;next赋值给头结点后继 if(Q-&gt;rear==p) //若队头就是队尾，删除后将rear指向头结点 Q-&lt;rear=Q-&gt;front; free(p); retrun OK;&#125;
总结栈（stack）限定仅在表尾进行插入和删除操作的线性表。 队列（queue）是值允许在一端进行插入操作，而另外一端进行删除操作的线性表。 对于栈：如果两个相同数据类型的栈，则可以用数组的两段作栈底的地方来让两个栈共享数据，可以最大化利用数组的空间。 对于队列：为了避免数组插入和删除时需要移动数据，于是引用了循环队列，使得队头和队尾进行数组中循环变化，结局了移动数据的时间损耗。

一、C 语言编译过程预处理、编译、汇编链接 gcc -E hello.c -o hello.i 1、预处理 gcc -S hello.i –o hello.s 2、编译 gcc -c hello.s -o hello.o 3、汇编 gcc hello.o -o hello_elf 4、链接 1、预编译 ​ 将.c 的头文件、宏展开 ​ 生成.i 文件 2、编译 ​ 将预处理的.i 文件生成 .s 汇编文件 3、汇编 ​ 将.s 汇编文件生成.o 目标文件 4、链接 ​ .o 文件链接成目标文件 二、include#include&lt;&gt; 用尖括号包括头文件，在系统指定的路径找到头文件 #include”” 用双引号包括头文件，先在当前目录下找到头文件，找不到再系统指定的路径下找 三、define定义 宏用 define 1、不带参数的宏#define PI 3.14//终止宏的定义 定义#undef PI
2、带参宏#define S(a,b) a*b 注意带参宏的形参 ab 没有类名 S(2,4)在预处理代替成字符串的形参 2 * 4 #include &lt;stdio.h&gt;#define S(a,b) ((a)*(b))int main()&#123; printf(&quot;%d\n&quot;,S(2,4)); //((2+8))*(4))=40 printf(&quot;%d\n&quot;,S(2 + 8,4));&#125;
3、带参宏和代餐函数的区​ 带参宏被调用多少次就会展开多少次，执行代码的时候没有函数调用的过程，不需要压栈弹栈。带参宏，浪费空间 ​ 带参函数，代码只有一份，存放在代码段，调用的时候去代码段指令，调用的时候要压栈弹栈。带参函数浪费了时间，节省了空间 四、选择性编译1、 #ifdef AAA 代码段一#else 代码段二#endif//如果在当前.c ifdef上边定义AAA，就编译代码段一，否则编译代码段二 #include AAA int main()&#123; #ifdef AAA printf(&quot;hello kitty\n&quot;); #else printf(&quot;hello ddd&quot;); #endif return 0; &#125;
2、 #ifndef AAA 代码段一#else 代码段二#endif //和第一种互补，用在防止头文件重复包含，用于多文件编程中.h的第一行就是#indef #endif结尾
3、 #if 表达式 代码块一#else 代码块二#endif//如果表达式为真，编译第一段，否则第二段//多用于注释多行代码

